const { importRecord } = require('./src/import-records');
const rows = [];
let marks = 0;
const database = {
  async insert(row) { rows.push({ ...row }); },
  async markImported() {
    marks += 1;
    if (marks === 1) throw new Error('timeout');
  }
};
importRecord(database, { externalId: 'customer-42', name: 'Example' })
  .then(() => console.log(JSON.stringify({ rows, marks }, null, 2)))
  .catch(error => { console.error(error); process.exitCode = 1; });
